  align-items: center;
  gap: 9px;
  padding: 8px 14px 8px 8px;
  border-color: rgba(239, 182, 97, 0.36);
  border-radius: 999px;
  transform: translateX(-50%);
  color: var(--bone);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  white-space: nowrap;
  animation: promptIn 0.22s ease both;
}

.interact-prompt[hidden] {
  display: none;
}

.interact-prompt kbd {
  display: grid;
  min-width: 24px;
  height: 24px;
  padding: 0 5px;
  place-items: center;
  border: 1px solid rgba(239, 182, 97, 0.45);
  border-radius: 50%;
  background: rgba(66, 44, 19, 0.6);
  color: var(--gold);
  font-family: var(--sans);
  font-size: 10px;
  box-shadow: 0 0 14px rgba(239, 182, 97, 0.12);
}

@keyframes promptIn {
  from { opacity: 0; transform: translate(-50%, 5px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.toast-stack {
  position: absolute;
  top: calc(126px + var(--safe-top));
  left: 50%;
  display: flex;
  width: min(400px, calc(100vw - 40px));
  flex-direction: column;
  gap: 7px;
  align-items: center;
  transform: translateX(-50%);
}

.toast {
  width: 100%;
  padding: 8px 12px 8px 11px;
  border: 1px solid rgba(236, 219, 188, 0.12);
  border-left: 2px solid var(--gold);
  border-radius: 2px 6px 6px 2px;
  background: rgba(8, 13, 21, 0.87);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.38);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  animation: toastIn 0.32s cubic-bezier(0.2, 0.9, 0.3, 1.2) both;
}

.toast.leaving {
  animation: toastOut 0.32s ease both;
}

.toast .t-title {
  color: var(--bone);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.toast .t-sub {
  margin-top: 2px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  line-height: 1.3;
}

.toast.alert {
  border-left-color: var(--red);
}

.toast.alert .t-title {
  color: #ef8a73;
}

.toast.good {
  border-left-color: var(--green);
}

.toast.good .t-title {
  color: #a6c8a8;
}

.toast.warn {
  border-left-color: var(--amber);
}

.toast.warn .t-title {
  color: var(--gold);
}

@keyframes toastIn {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes toastOut {
  to { opacity: 0; transform: translateY(-5px); }
}

.center-banner {
  position: absolute;
  top: 30%;
  left: 50%;
  display: flex;
  width: min(720px, 90vw);
  flex-direction: column;
  align-items: center;
  opacity: 0;
  pointer-events: none;
  text-align: center;
  transform: translate(-50%, 10px);
  transition: opacity 0.5s ease, transform 0.7s ease;
}

.center-banner.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

.center-banner span {
  margin-bottom: 8px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
}

.center-banner strong {
  color: var(--bone);
  font-family: var(--serif);
  font-size: clamp(34px, 5vw, 64px);
  font-weight: 400;
  letter-spacing: 0.06em;
  line-height: 1;
  text-shadow: 0 2px 28px rgba(0, 0, 0, 0.85);
}

.center-banner small {
  margin-top: 11px;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  letter-spacing: 0.03em;
  text-shadow: 0 2px 14px #000;
}

.center-banner.night span,
.center-banner.night strong {
  color: #ef8069;
}

.center-banner.night strong {
  text-shadow: 0 0 34px rgba(197, 52, 35, 0.55), 0 2px 22px #000;
}

.center-banner.dusk span,
.center-banner.dusk strong {
  color: #f2a266;
}

.center-banner.dawn span,
.center-banner.dawn strong {
  color: #f1d49a;
}

/* Crosshair */

.crosshair {
  position: absolute;
  top: 0;
  left: 0;
  width: 26px;
  height: 26px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  --ch: rgba(239, 228, 207, 0.72);
}

.crosshair.active {
  opacity: 1;
}

.crosshair i {
  position: absolute;
  background: var(--ch);
}

.crosshair i:nth-child(1) {
  top: 12px;
  left: 1px;
  width: 6px;
  height: 1px;
}

.crosshair i:nth-child(2) {
  top: 12px;
  right: 1px;
  width: 6px;
  height: 1px;
}

.crosshair i:nth-child(3) {
  top: 1px;
  left: 12px;
  width: 1px;
  height: 6px;
}

.crosshair i:nth-child(4) {
  bottom: 1px;
  left: 12px;
  width: 1px;
  height: 6px;
}

.crosshair span {
  position: absolute;
  top: 11px;
  left: 11px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--ch);
  box-shadow: 0 0 5px rgba(239, 228, 207, 0.4);
}

.crosshair.hot {
  --ch: rgba(242, 104, 80, 0.95);
}

.crosshair.hot span {
  box-shadow: 0 0 8px rgba(255, 75, 50, 0.9);
}

/* Mobile controls */

#mobileControls {
  display: none;
}

.joystick {
  position: absolute;
  bottom: calc(20px + var(--safe-bottom));
  left: calc(20px + var(--safe-left));
  width: 118px;
  height: 118px;
  pointer-events: auto;
  touch-action: none;
}

.stick-base {
  position: relative;
  width: 100%;
  height: 100%;
  border: 1px solid rgba(236, 219, 188, 0.18);
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(239, 182, 97, 0.06), transparent 62%),
    rgba(7, 12, 20, 0.38);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.38);
}

.stick-base::before,
.stick-base::after {
  content: "";
  position: absolute;
  background: rgba(236, 219, 188, 0.08);
}

.stick-base::before {

.stick-base::before {
  top: 50%;
  left: 12%;
  width: 76%;
  height: 1px;
}

.stick-base::after {
  top: 12%;
  left: 50%;
  width: 1px;
  height: 76%;
}

.stick-nub {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 47px;
  height: 47px;
  margin: -23.5px 0 0 -23.5px;
  border: 1px solid rgba(239, 182, 97, 0.38);
  border-radius: 50%;
  background: radial-gradient(circle at 34% 30%, rgba(239, 182, 97, 0.24), rgba(43, 35, 24, 0.55));
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.42);
}

.use-btn,
.fire-btn {
  position: absolute;
  border-radius: 50%;
  font-weight: 700;
  letter-spacing: 0.09em;
  pointer-events: auto;
  touch-action: manipulation;
}

.use-btn {
  right: calc(46px + var(--safe-right));
  bottom: calc(117px + var(--safe-bottom));
  width: 60px;
  height: 60px;
  border: 1px solid rgba(239, 182, 97, 0.4);
  background: rgba(18, 22, 27, 0.72);
  color: var(--gold);
  font-size: 9px;
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.38);
}

.use-btn:active {
  background: rgba(88, 61, 28, 0.8);
}

.fire-btn {
  right: calc(23px + var(--safe-right));
  bottom: calc(25px + var(--safe-bottom));
  width: 83px;
  height: 83px;
  border: 1px solid rgba(213, 83, 63, 0.55);
  background:
    radial-gradient(circle at 35% 30%, rgba(213, 83, 63, 0.32), rgba(61, 23, 20, 0.72));
  color: #f2b09f;
  font-size: 11px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.48), inset 0 0 22px rgba(213, 83, 63, 0.12);
}

.fire-btn:active,
.fire-btn.firing {
  background: radial-gradient(circle at 35% 30%, rgba(236, 111, 83, 0.54), rgba(102, 35, 27, 0.82));
  color: #fff1e6;
}

/* ---------- Screens ---------- */

.screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  opacity: 1;
  visibility: visible;
  transition: opacity 0.55s ease, visibility 0.55s;
}

.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

/* Menu */

.menu-screen {
  background:
    radial-gradient(ellipse at 72% 60%, transparent 0%, rgba(7, 11, 19, 0.15) 42%, rgba(7, 11, 19, 0.78) 100%),
    linear-gradient(180deg, rgba(7, 11, 19, 0.12) 0%, rgba(7, 11, 19, 0.18) 45%, rgba(7, 11, 19, 0.82) 100%);
}

.menu-scrim {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 16% 60%, rgba(7, 10, 17, 0.64) 0%, transparent 58%),
    linear-gradient(90deg, rgba(6, 10, 17, 0.82) 0%, rgba(6, 10, 17, 0.3) 48%, transparent 70%);
}

.menu-layout {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4vw;
  padding: clamp(24px, 7vw, 100px);
  padding-top: calc(clamp(24px, 7vw, 100px) + var(--safe-top));
  padding-bottom: calc(clamp(40px, 8vh, 90px) + var(--safe-bottom));
}

.menu-content {
  position: relative;
  width: min(630px, 62vw);
  animation: menuRise 0.9s ease both;
}

@keyframes menuRise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

.menu-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.43em;
}

.menu-kicker i {
  width: 28px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(239, 182, 97, 0.7));
}

.menu-kicker i:last-child {
  background: linear-gradient(90deg, rgba(239, 182, 97, 0.7), transparent);
}

.title {
  margin: 0;
  color: #f3e8d3;
  font-family: var(--serif);
  font-size: clamp(64px, 9.6vw, 126px);
  font-weight: 400;
  letter-spacing: 0.055em;
  line-height: 0.84;
  text-shadow:
    0 3px 32px rgba(0, 0, 0, 0.6),
    0 0 90px rgba(218, 145, 73, 0.1);
}

.title span {
  color: var(--gold);
  text-shadow:
    0 0 46px rgba(233, 157, 76, 0.24),
    0 4px 32px rgba(0, 0, 0, 0.6);
}

.menu-tagline {
  margin: 20px 0 0;
  color: #d8c9b0;
  font-family: var(--serif);
  font-size: clamp(15px, 1.65vw, 20px);
  font-style: italic;
  letter-spacing: 0.05em;
}

.menu-story {
  max-width: 490px;
  margin: 18px 0 0;
  color: #a59d8e;
  font-size: 13px;
  line-height: 1.65;
}

.menu-rule {
  display: flex;
  width: min(430px, 100%);
  align-items: center;
  gap: 12px;
  margin: 24px 0 14px;
  color: rgba(213, 83, 63, 0.9);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.23em;
}

.menu-rule span {
  height: 1px;
  flex: 1;
  background: linear-gradient(90deg, transparent, rgba(213, 83, 63, 0.4));
}

.menu-rule span:last-child {
  background: linear-gradient(90deg, rgba(213, 83, 63, 0.4), transparent);
}

.menu-warning {
  max-width: 450px;
  margin: 0;
  color: #c98d7b;
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  line-height: 1.55;
}

.menu-actions {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-top: 25px;
}

.primary-btn {
  position: relative;
  min-width: 170px;
  padding: 14px 27px;
  overflow: hidden;
  border: 1px solid rgba(239, 182, 97, 0.62);
  border-radius: 2px;
  background:
    linear-gradient(180deg, rgba(170, 108, 43, 0.55), rgba(92, 59, 26, 0.4));
  color: #fae3b7;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-align: center;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.32), inset 0 1px rgba(255, 235, 194, 0.14);
  transition: border-color 0.22s, background 0.22s, box-shadow 0.22s, transform 0.22s;
}

.primary-btn::after {
  content: "";
  position: absolute;
  top: 0;
  left: -80%;
  width: 60%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 235, 194, 0.13), transparent);
  transform: skewX(-18deg);
  transition: left 0.55s ease;
}

.primary-btn:hover,
.primary-btn:focus-visible {
  border-color: #ffd790;
  background: linear-gradient(180deg, rgba(196, 127, 51, 0.68), rgba(104, 67, 28, 0.5));
  box-shadow: 0 10px 36px rgba(0, 0, 0, 0.4), 0 0 24px rgba(239, 182, 97, 0.14);
  transform: translateY(-1px);
}

.primary-btn:hover::after {
  left: 125%;
}

.primary-btn:active {
  transform: translateY(0);
}

.best-line {
  color: var(--muted);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.18em;
}

.best-line b {
  margin-left: 6px;
  color: var(--gold);
  font-family: var(--serif);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 0.04em;
}

.menu-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 9px 18px;
  margin-top: 29px;
  padding-top: 16px;
  border-top: 1px solid rgba(236, 219, 188, 0.1);
  color: rgba(165, 157, 142, 0.72);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.menu-controls span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.menu-controls kbd {
  padding: 3px 5px;
  border: 1px solid rgba(236, 219, 188, 0.2);
  border-radius: 2px;
  color: var(--bone-dim);
  font-family: var(--sans);
  font-size: 7px;
  letter-spacing: 0.06em;
}

.menu-aside {
  width: min(230px, 20vw);
  padding-left: 26px;
  border-left: 1px solid rgba(239, 182, 97, 0.18);
  color: rgba(208, 197, 178, 0.66);
}

.aside-stamp {
  margin-bottom: 14px;
  color: rgba(239, 182, 97, 0.5);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.24em;
  line-height: 1.7;
}

.aside-stamp b {
  color: rgba(239, 182, 97, 0.78);
  font-size: 12px;
}

.menu-aside p {
  margin: 0;
  font-family: var(--serif);
  font-size: 13px;
  font-style: italic;
  line-height: 1.65;
}

.menu-foot {
  position: absolute;
  right: clamp(24px, 7vw, 100px);
  bottom: calc(22px + var(--safe-bottom));
  color: rgba(145, 139, 127, 0.52);
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

/* Overlay screens */

.overlay-screen {
  display: grid;
  padding: 24px;
  place-items: center;
  background:
    radial-gradient(ellipse at center, rgba(13, 20, 31, 0.4) 0%, rgba(4, 7, 12, 0.9) 100%);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
}

.dawn-screen {
  background:
    radial-gradient(ellipse at 50% 20%, rgba(214, 152, 82, 0.26) 0%, transparent 48%),
    radial-gradient(ellipse at center, rgba(34, 28, 25, 0.5) 0%, rgba(6, 9, 15, 0.92) 100%);
}

.death-screen {
  background:
    radial-gradient(ellipse at 50% 45%, rgba(117, 26, 21, 0.28) 0%, transparent 56%),
    radial-gradient(ellipse at center, rgba(26, 12, 13, 0.62) 0%, rgba(4, 6, 10, 0.94) 100%);
}

.screen-card {
  width: min(650px, 92vw);
  padding: clamp(25px, 4.5vw, 48px);
  border: 1px solid rgba(236, 219, 188, 0.17);
  border-radius: 4px;
  background:
    linear-gradient(155deg, rgba(24, 31, 43, 0.7), rgba(7, 11, 18, 0.9));
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.65), inset 0 1px rgba(255, 240, 210, 0.05);
  text-align: center;
}

.screen-card.compact {
  width: min(430px, 92vw);
}

.screen-kicker {
  margin-bottom: 10px;
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.38em;
}

.death-card .screen-kicker {
  color: #df7863;
}

.screen-card h2 {
  margin: 0;
  color: var(--bone);
  font-family: var(--serif);
  font-size: clamp(36px, 5vw, 62px);
  font-weight: 400;
  letter-spacing: 0.02em;
  line-height: 1;
}

.screen-card > p {
  max-width: 480px;
  margin: 17px auto 0;
  color: var(--bone-dim);
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.55;
}

.screen-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 27px;
}

.ghost-btn {
  min-width: 140px;
  padding: 14px 22px;
  border: 1px solid rgba(236, 219, 188, 0.22);
  border-radius: 2px;
  background: transparent;
  color: var(--bone-dim);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s, background 0.2s;
}

.ghost-btn:hover,
.ghost-btn:focus-visible {
  border-color: rgba(236, 219, 188, 0.55);
  background: rgba(236, 219, 188, 0.06);
  color: var(--bone);
}

.screen-hint {
  margin-top: 20px;
  color: rgba(145, 139, 127, 0.6);
  font-size: 8px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin: 25px 0 0;
  overflow: hidden;
  border: 1px solid rgba(236, 219, 188, 0.1);
  border-radius: 3px;
  background: rgba(236, 219, 188, 0.1);
}

.stat-grid > div {
  padding: 13px 7px 11px;
  background: rgba(8, 13, 22, 0.82);
}

.stat-grid span {
  display: block;
  color: var(--muted);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.13em;
}

.stat-grid b {
  display: block;
  margin-top: 5px;
  color: var(--bone);
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 400;
}

.dawn-card .stat-grid b {
  color: #f1d398;
}

.death-card .stat-grid b {
  color: #e69782;
}

.dawn-advice {
  color: #d6b77e !important;
}

.death-advice {
  color: #c58d7e !important;
}

/* ---------- Responsive ---------- */

@media (max-width: 980px) {
  .menu-content {
    width: min(580px, 72vw);
  }

  .menu-aside {
    display: none;
  }
}

@media (max-width: 820px) {
  .status-panel {
    top: calc(10px + var(--safe-top));
    left: calc(10px + var(--safe-left));
    width: 174px;
    padding: 9px 10px 9px;
    border-radius: 3px 12px 12px 12px;
  }

  .brand-row {
    gap: 5px;
    margin-bottom: 5px;
  }

  }

  .brand-name {
    font-size: 7px;
    letter-spacing: 0.25em;
  }

  .brand-mark {
    font-size: 8px;
  }

  .best-badge {
    padding: 1px 4px;
    font-size: 6px;
    letter-spacing: 0.09em;
  }

  .day-row {
    gap: 6px;
  }

  .day-row h1 {
    font-size: 21px;
  }

  .phase-chip {
    padding: 2px 4px;
    font-size: 6px;
    letter-spacing: 0.11em;
  }

  .timeline {
    margin-top: 7px;
    height: 5px;
  }

  .timeline-track {
    height: 3px;
  }

  .time-row {
    gap: 5px;
    margin-top: 4px;
    font-size: 7.5px;
  }

  .objective {
    max-width: 74px;
    font-size: 6px;
  }

  .vital-row {
    gap: 5px;
    margin-top: 7px;
    padding-top: 7px;
  }

  .vital-icon {
    width: 8px;
    height: 7px;
    transform: rotate(-45deg) scale(0.8);
  }

  .vital-icon::before {
    width: 8px;
    height: 7px;
    top: -4px;
  }

  .vital-icon::after {
    width: 8px;
    height: 7px;
    left: 4px;
  }

  .vital-track {
    height: 4px;
  }

  .vital-row b {
    min-width: 20px;
    font-size: 8px;
  }

  .map-panel {
    top: calc(10px + var(--safe-top));
    right: calc(10px + var(--safe-right));
    width: 120px;
    padding: 6px;
    border-radius: 12px 3px 12px 12px;
  }

  .map-head {
    margin-bottom: 4px;
    font-size: 5.5px;
  }

  .live-dot {
    width: 4px;
    height: 4px;
  }

  #minimap {
    width: 106px;
    height: 69px;
    border-radius: 5px;
  }

  .map-foot {
    margin-top: 4px;
    font-size: 5.5px;
    letter-spacing: 0.06em;
  }

  .sys-buttons {
    top: calc(98px + var(--safe-top));
    right: calc(10px + var(--safe-right));
    gap: 5px;
  }

  .sys-btn {
    width: 27px;
    height: 27px;
  }

  .sys-btn svg {
    width: 12px;
    height: 12px;
  }

  .shelter-panel {
    top: auto;
    right: calc(10px + var(--safe-right));
    bottom: calc(155px + var(--safe-bottom));
    left: calc(10px + var(--safe-left));
    width: auto;
    max-height: 36vh;
    padding: 12px;
    border-radius: 12px;
    transform: translateY(14px);
  }

  .shelter-panel.open {
    transform: translateY(0);
  }

  .sp-head h2 {
    font-size: 19px;
  }

  .sp-kicker {
    font-size: 5.5px;
  }

  .haunt-badge {
    font-size: 6px;
    padding: 3px 4px;
  }

  .sp-perk {
    margin: 4px 0 9px;
    font-size: 10px;
  }

  .sp-meta {
    font-size: 5.5px;
    letter-spacing: 0.06em;
  }

  .bar-row {
    font-size: 6px;
  }

  .bar-row b {
    font-size: 8px;
  }

  .bar-track {
    height: 5px;
  }

  .fort-grid {
    grid-template-columns: repeat(4, 1fr);
    gap: 4px;
    margin-top: 9px;
  }

  .fort-btn {
    padding: 6px;
    gap: 3px;
  }

  .fort-top {
    gap: 3px;
  }

  .fort-top b {
    font-size: 6.5px;
    letter-spacing: 0;
  }

  .fort-top em {
    font-size: 7px;
  }

  .fort-btn small {
    display: none;
  }

  .weapon-upgrade {
    margin-top: 5px;
    padding: 6px 8px;
  }

  .weapon-upgrade b {
    font-size: 7px;
  }

  .weapon-upgrade small {
    display: none;
  }

  .weapon-cost b {
    font-size: 8px;
  }

  .haunt-warning {
    margin-top: 7px;
    padding: 5px 6px;
    font-size: 7.5px;
  }

  .claim-btn {
    margin-top: 8px;
    padding: 8px;
    font-size: 8px;
  }

  .resource-tray {
    top: calc(126px + var(--safe-top));
    bottom: auto;
    gap: 10px;
    padding: 5px 12px;
    border-radius: 999px;
  }

  .res {
    gap: 4px;
    font-size: 6px;
    letter-spacing: 0.08em;
  }

  .res b {
    font-size: 10px;
  }

  .res-dot {
    width: 4px;
    height: 4px;
  }

  .weapon-box {
    display: none;
  }

  .interact-prompt {
    bottom: calc(151px + var(--safe-bottom));
    font-size: 8px;
    padding: 6px 11px 6px 6px;
  }

  .interact-prompt kbd {
    min-width: 20px;
    height: 20px;
    font-size: 8px;
  }

  .toast-stack {
    top: calc(158px + var(--safe-top));
    width: calc(100vw - 30px);
    gap: 5px;
  }

  .toast {
    padding: 6px 9px;
  }

  .toast .t-title {
    font-size: 7.5px;
  }

  .toast .t-sub {
    font-size: 9.5px;
  }

  .center-banner {
    top: 27%;
  }

  .center-banner strong {
    font-size: clamp(29px, 9vw, 48px);
  }

  .center-banner small {
    font-size: 11px;
  }

  #mobileControls {
    display: block;
  }

  .crosshair {
    display: none;
  }

  .menu-layout {
    align-items: flex-end;
    justify-content: center;
    padding: calc(20px + var(--safe-top)) 22px calc(52px + var(--safe-bottom));
  }

  .menu-content {
    width: 100%;
    max-width: 520px;
    align-self: flex-end;
  }

  .menu-scrim {
    background:
      linear-gradient(0deg, rgba(6, 10, 17, 0.96) 0%, rgba(6, 10, 17, 0.7) 46%, rgba(6, 10, 17, 0.08) 78%),
      linear-gradient(90deg, rgba(6, 10, 17, 0.42), transparent);
  }

  .menu-kicker {
    margin-bottom: 9px;
    font-size: 7px;
    letter-spacing: 0.3em;
  }

  .menu-kicker i {
    width: 18px;
  }

  .title {
    font-size: clamp(54px, 15vw, 82px);
  }

  .menu-tagline {
    margin-top: 14px;
    font-size: 14px;
  }

  .menu-story {
    margin-top: 12px;
    font-size: 11.5px;
    line-height: 1.55;
  }

  .menu-rule {
    margin: 16px 0 10px;
    font-size: 6.5px;
  }

  .menu-warning {
    font-size: 10.5px;
  }

  .menu-actions {
    gap: 13px;
    margin-top: 18px;
  }

  .primary-btn {
    min-width: 150px;
    padding: 12px 20px;
    font-size: 9px;
  }

  .best-line {
    font-size: 6.5px;
  }

  .best-line b {
    font-size: 12px;
  }

  .menu-controls {
    gap: 7px 12px;
    margin-top: 18px;
    padding-top: 12px;
    font-size: 6.5px;
  }

  .menu-controls kbd {
    font-size: 6px;
  }

  .menu-foot {
    right: 0;
    bottom: calc(16px + var(--safe-bottom));
    left: 0;
    font-size: 6px;
    text-align: center;
  }

  .screen-card {
    padding: 24px 19px;
  }

  .stat-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .stat-grid b {
    font-size: 19px;
  }

  .screen-actions {
    flex-direction: column;
    gap: 9px;
    margin-top: 21px;
  }

  .screen-actions .primary-btn,
  .screen-actions .ghost-btn {
    width: 100%;
  }

  .screen-hint {
    font-size: 7px;
  }
}

@media (max-width: 380px) {
  .status-panel {
    width: 154px;
  }

  .map-panel {
    width: 110px;
  }

  #minimap {
    width: 96px;
    height: 63px;
  }

  .day-row h1 {
    font-size: 19px;
  }

  .resource-tray {
    gap: 7px;
    padding: 4px 9px;
  }

  .shelter-panel {
    bottom: calc(148px + var(--safe-bottom));
  }

  .fort-grid {
    grid-template-columns: 1fr 1fr;
  }

  .fort-btn small {
    display: block;
  }
}

@media (max-height: 600px) and (orientation: landscape) {
  .status-panel {
    width: 230px;
  }

  .map-panel {
    width: 150px;
  }

  #minimap {
    width: 136px;
    height: 88px;
  }

  .sys-buttons {
    top: calc(126px + var(--safe-top));
  }

  .shelter-panel {
    top: calc(105px + var(--safe-top));
    right: calc(10px + var(--safe-right));
    bottom: auto;
    left: auto;
    width: 300px;
    max-height: calc(100vh - 120px);
  }

  .resource-tray {
    top: auto;
    bottom: calc(10px + var(--safe-bottom));
    left: 50%;
  }

  .interact-prompt {
    bottom: calc(76px + var(--safe-bottom));
  }

  .joystick {
    width: 98px;
    height: 98px;
  }

  .stick-nub {
    width: 40px;
    height: 40px;
    margin: -20px 0 0 -20px;
  }

  .fire-btn {
    width: 72px;
    height: 72px;
    right: calc(18px + var(--safe-right));
    bottom: calc(18px + var(--safe-bottom));
  }

  .use-btn {
    right: calc(35px + var(--safe-right));
    bottom: calc(98px + var(--safe-bottom));
    width: 52px;
    height: 52px;
  }
}

@media (hover: hover) and (pointer: fine) {
  #world {
    cursor: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
